```java
// ─── File: SecureAccessDemo.java ───
// This file contains multiple classes for the runnable demo.
// In a real project each class would be in its own file.
package com.bank.secure;

import java.util.logging.*;

public class SecureAccessDemo {
    private static final Logger log = Logger.getLogger("SecureAccess");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ECS task role grants least-privilege S3 + Secrets Manager access.
        IamRole taskRole = new IamRole("transfer-task-role");
        SecretStore secrets = new SecretStore();
        secrets.put("prod/nbi-ledger/credentials", "password-v1");

        SecureApp app = new SecureApp(taskRole, secrets);

        log.info(() -> "Temporary credentials from role: " + taskRole.issueTemporaryCredentials());
        log.info(() -> "S3 call using role (no hardcoded keys): " + app.readFromS3("nbi-statements"));
        log.info(() -> "DB password fetched at runtime: " + app.currentDbPassword());

        // Automatic rotation changes the secret; app refreshes and picks it up.
        secrets.rotate("prod/nbi-ledger/credentials", "password-v2");
        log.warning(() -> "Secret rotated by Secrets Manager (zero downtime)");
        log.info(() -> "DB password after rotation: " + app.refreshAndGetDbPassword());
    }
}

// ─── Would be in SecureApp.java ───
class SecureApp {
    private final IamRole role;
    private final SecretStore secrets;
    private String cachedPassword;

    SecureApp(IamRole role, SecretStore secrets) {
        this.role = role; this.secrets = secrets;
        this.cachedPassword = secrets.get("prod/nbi-ledger/credentials");
    }

    // Uses the role's temporary credentials; the SDK would do this transparently.
    String readFromS3(String bucket) {
        String creds = role.issueTemporaryCredentials();
        return "GetObject on " + bucket + " authorized by " + creds;
    }

    String currentDbPassword() { return cachedPassword; }

    // On rotation (or auth failure) refresh from Secrets Manager.
    String refreshAndGetDbPassword() {
        this.cachedPassword = secrets.get("prod/nbi-ledger/credentials");
        return cachedPassword;
    }
}

// ─── Would be in IamRole.java ───
class IamRole {
    private final String roleName;
    private int tokenSeq = 0;
    IamRole(String roleName) { this.roleName = roleName; }
    // Short-lived credentials that rotate automatically — never static keys.
    String issueTemporaryCredentials() {
        return roleName + "#temp-" + (++tokenSeq) + " (expires ~1h, auto-rotated)";
    }
}

// ─── Would be in SecretStore.java ───
class SecretStore {
    private final java.util.Map<String, String> values = new java.util.HashMap<>();
    private final java.util.Map<String, Integer> versions = new java.util.HashMap<>();

    void put(String id, String value) { values.put(id, value); versions.put(id, 1); }
    String get(String id) { return values.get(id) + " (KMS-encrypted, v" + versions.get(id) + ")"; }
    void rotate(String id, String newValue) {
        values.put(id, newValue);
        versions.merge(id, 1, Integer::sum);
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
